const client = axios.create({ baseURL: 'https://pokeapi.co/api/v2', timeout: 15000 });
const responses = await Promise.all(
  batch.map((p) => client.get<PokemonResponse>(`/pokemon/${p.name}`)),
);

function compare(a: Pokemon, b: Pokemon, key: SortKey): number {
  if (key === 'name') return a.name.localeCompare(b.name);
  return a[key] - b[key] || a.id - b.id;
}

const ids = stateIds?.includes(currentId) ? stateIds : pokemon.map((p) => p.id);
const prevId = ids[(index - 1 + ids.length) % ids.length];
const nextId = ids[(index + 1) % ids.length];
